import { radius, useColors } from "@/lib/ui";
import type { Scale } from "./geometry";

export const STAGE_LABELS = {
  inBed: "In bed",
  awake: "Awake",
  rem: "REM",
  core: "Core",
  deep: "Deep",
} as const;

/** Depth of sleep reads as depth of one hue; awake is the page background with a border. */
